customCSS:
.t, .history { color: #008000; }
.join { color: #008000; }
.part, .quit { color: #008000; }
.kick, .error { color: #cd3131; }
.notice { color: #795e26; }
.action { color: #af00db; }
.mode, .nick, .topic, .server { color: #267f99; }
.highlight { color: #000000; background-color: #add6ff; border-left: 3px solid #af00db; padding-left: 8px; }
.reply { color: #008000; border-left: 2px solid #0000ff; padding-left: 6px; }
.oper { color: #ffffff; background-color: #795e26; }
.reactions { color: #0000ff; background-color: #f3f3f3; }
.card { background-color: #f3f3f3; border-color: #008000; }
.card-title { color: #0000ff; }
.card-desc { color: #008000; }
.daychange { color: #008000; border-color: #f3f3f3; }
